mapper.select:
SELECT FROM blog_posts p LEFT JOIN files f ON f.id = p.cover_file_id
p.deleted_at IS NULL AND p.status = 'ACTIVE' AND (p.published_at IS NULL OR p.published_at <= now()) AND p.status = #{status} AND (p.title ILIKE CONCAT('%', #{keyword}, '%') OR p.excerpt ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.published_at DESC NULLS LAST, p.created_at DESC LIMIT #{limit} OFFSET #{offset}
